const a={name:"ECDSA",namedCurve:"P-256"},s={name:"ECDSA",hash:"SHA-256"},i="ABCDEFGHJKLMNPQRSTUVWXYZ23456789",o=new TextEncoder;export const base64url={encode(e){let r="";for(const t of new Uint8Array(e))r+=String.fromCharCode(t);return btoa(r).replace(/\+/g,"-").replace(/\//g,"_").replace(/=+$/,"")},decode(e){if(typeof e!="string"||!/^[A-Za-z0-9_-]*$/.test(e))throw new Error("Not base64url.");return Uint8Array.from(atob(e.replace(/-/g,"+").replace(/_/g,"/")),r=>r.charCodeAt(0))}};export async function sha256Hex(e){const r=new Uint8Array(await crypto.subtle.digest("SHA-256",o.encode(e)));return Array.from(r,t=>t.toString(16).padStart(2,"0")).join("")}export function isPublicKey(e){if(typeof e!="string"||!/^[A-Za-z0-9_-]{87}$/.test(e))return!1;try{const r=base64url.decode(e);return r.length===65&&r[0]===4}catch{return!1}}export async function browserCode(e){const r=new Uint8Array(await crypto.subtle.digest("SHA-256",base64url.decode(e))),t=Array.from(r.subarray(0,6),n=>i[n%32]).join("");return`${t.substring(0,3)}-${t.substring(3)}`}export function generateKeys(){return crypto.subtle.generateKey(a,!1,["sign","verify"])}export async function exportPublicKey(e){return base64url.encode(await crypto.subtle.exportKey("raw",e.publicKey))}export async function sign(e,r){return base64url.encode(await crypto.subtle.sign(s,e,o.encode(r.join(`
`))))}export async function verify(e,r,t){try{if(!isPublicKey(e))return!1;const n=base64url.decode(r);if(n.length!==64)return!1;const c=await crypto.subtle.importKey("raw",base64url.decode(e),a,!1,["verify"]);return await crypto.subtle.verify(s,c,n,o.encode(t.join(`
`)))}catch{return!1}}export async function offerLines(e,r,t){return["taskproxy-remote-offer-v1",`${e}`,`${r}`,await sha256Hex(t)]}export async function answerLines(e,r,t,n){return["taskproxy-remote-answer-v1",`${e}`,`${r}`,await sha256Hex(t),typeof n=="string"?await sha256Hex(n):""]}
